def concept(topic, title, mechanism, controls, case, rule, source, codes, chart=None):
    """mechanism: four plain steps. controls: four (heading, explanation) good-practice pairs.
    case: (situation, what can go wrong, what you do, what you keep)."""
    return dict(topic=topic, title=title, mechanism=mechanism, controls=controls,
                case=case, rule=rule, source=SOURCES[source], codes=codes, chart=chart)


